===== custom-theme.js =====
/* ===========================================================
   Nxeon Mail - SOGo custom theme (dark-navy + violet)
   Loaded into SOGo as WebServerResources/js/theme.js
   Mirrors the shape of mailcow's shipped example so it is
   guaranteed to compile against Angular Material's theming.
   =========================================================== */
(function() {
  'use strict';
  angular.module('SOGo.Common')
    .config(configure);

  configure.$inject = ['$mdThemingProvider'];
  function configure($mdThemingProvider) {

    // Nxeon violet primary palette
    var nxeonViolet = $mdThemingProvider.extendPalette('deep-purple', {
      '50':  'efeaff',
      '100': 'd6c9ff',
      '200': 'b8a3ff',
      '300': '9a7dff',
      '400': '8461fb',
      '500': '6f47f5',
      '600': '6340e0',
      '700': '5a37d6',
      '800': '4a2db0',
      '900': '3a2290',
      'A100': 'b8a3ff',
      'A200': '8a63ff',
      'A400': '6f47f5',
      'A700': '5a37d6',
      'contrastDefaultColor': 'light'
    });

    // Nxeon accent blue palette
    var nxeonBlue = $mdThemingProvider.extendPalette('blue', {
      '400': '5b98f8',
      '500': '3b82f6',
      '600': '2f6fe0',
      '700': '2560c8',
      'A200': '3b82f6',
      'A400': '3b82f6',
      'A700': '2560c8',
      'contrastDefaultColor': 'light'
    });

    // Nxeon dark-navy background palette
    var nxeonNavy = $mdThemingProvider.extendPalette('grey', {
      '50':  '19223a',
      '100': '141c30',
      '200': '111829',
      '300': '0f1524',
      '400': '0c1120',
      '500': '0a101f',
      '600': '090d1a',
      '700': '070b16',
      '800': '060a14',
      '900': '04070f',
      'A100': '141c30',
      'A200': '0a101f',
      'A400': '060a14',
      'A700': '04070f',
      'contrastDefaultColor': 'light',
      'contrastLightColors': '50 100 200 300 400 500 600 700 800 900 A100 A200 A400 A700'
    });

    $mdThemingProvider.definePalette('nxeon-violet', nxeonViolet);
    $mdThemingProvider.definePalette('nxeon-blue', nxeonBlue);
    $mdThemingProvider.definePalette('nxeon-navy', nxeonNavy);

    $mdThemingProvider.theme('default')
      .primaryPalette('nxeon-violet', {
        'default': '500',
        'hue-1': 'A200',
        'hue-2': '700',
        'hue-3': '900'
      })
      .accentPalette('nxeon-blue', {
        'default': '500',
        'hue-1': '400',
        'hue-2': '600',
        'hue-3': '700'
      })
      .warnPalette('red')
      .backgroundPalette('nxeon-navy', {
        'default': '500',
        'hue-1': '400',
        'hue-2': '300',
        'hue-3': '900'
      });

    $mdThemingProvider.generateThemesOnDemand(false);
  }
})();

